extends SceneTree

# ADR-0015 probe: analytic axis clamp vs literal 1-px stepper, plus engine integer facts.
# Integer-only. Run: Godot --headless --script sweep_probe.gd

const HW: int = 8
const FH: int = 8

var n: int = 0
var rx0: PackedInt32Array = PackedInt32Array()
var ry0: PackedInt32Array = PackedInt32Array()
var rx1: PackedInt32Array = PackedInt32Array()
var ry1: PackedInt32Array = PackedInt32Array()
var in_e: PackedByteArray = PackedByteArray()
var exempt: bool = false
var sx0: int = 0
var sy0: int = 0
var sx1: int = 0
var sy1: int = 0
var rng: RandomNumberGenerator = RandomNumberGenerator.new()


func area(bx0: int, by0: int, bx1: int, by1: int, i: int) -> int:
	var ox: int = maxi(0, mini(bx1, rx1[i]) - maxi(bx0, rx0[i]))
	var oy: int = maxi(0, mini(by1, ry1[i]) - maxi(by0, ry0[i]))
	return ox * oy


func in_section(x: int, y: int) -> bool:
	return x >= sx0 and x < sx1 and y >= sy0 and y < sy1


func step_ok(px: int, py: int, dx: int, dy: int) -> bool:
	var nx: int = px + dx
	var ny: int = py + dy
	for i in range(n):
		var a1: int = area(nx - HW, ny, nx + HW, ny + FH, i)
		if in_e[i] == 1:
			var a0: int = area(px - HW, py, px + HW, py + FH, i)
			if a1 > a0:
				return false
		elif a1 > 0:
			return false
	if exempt and not in_section(nx, ny):
		return false
	return true


func oracle_axis(px: int, py: int, steps: int, axis: int) -> int:
	var d: int = signi(steps)
	var moved: int = 0
	for k in range(absi(steps)):
		var dx: int = d if axis == 0 else 0
		var dy: int = d if axis == 1 else 0
		if not step_ok(px, py, dx, dy):
			break
		px += dx
		py += dy
		moved += 1
	return moved * d


func analytic_axis(px: int, py: int, steps: int, axis: int) -> int:
	if steps == 0:
		return 0
	var d: int = signi(steps)
	var limit: int = absi(steps)
	for i in range(n):
		if in_e[i] == 1:
			continue
		if axis == 0:
			if not (ry0[i] < py + FH and ry1[i] > py):
				continue
			if d > 0:
				if rx0[i] >= px + HW:
					limit = mini(limit, rx0[i] - (px + HW))
			else:
				if rx1[i] <= px - HW:
					limit = mini(limit, (px - HW) - rx1[i])
		else:
			if not (rx0[i] < px + HW and rx1[i] > px - HW):
				continue
			if d > 0:
				if ry0[i] >= py + FH:
					limit = mini(limit, ry0[i] - (py + FH))
			else:
				if ry1[i] <= py:
					limit = mini(limit, py - ry1[i])
	if not exempt:
		return limit * d
	var moved: int = 0
	for k in range(limit):
		var dx: int = d if axis == 0 else 0
		var dy: int = d if axis == 1 else 0
		var nx: int = px + dx
		var ny: int = py + dy
		var ok: bool = true
		for i in range(n):
			if in_e[i] == 1:
				if area(nx - HW, ny, nx + HW, ny + FH, i) > area(px - HW, py, px + HW, py + FH, i):
					ok = false
					break
		if not ok or not in_section(nx, ny):
			break
		px = nx
		py = ny
		moved += 1
	return moved * d


func gen() -> void:
	n = rng.randi_range(0, 16)
	rx0.resize(n)
	ry0.resize(n)
	rx1.resize(n)
	ry1.resize(n)
	in_e.resize(n)
	var kind: int = rng.randi_range(0, 2)
	for i in range(n):
		var w: int = rng.randi_range(1, 40)
		var h: int = rng.randi_range(1, 40)
		if kind == 0:
			w = rng.randi_range(1, 3)
		var x0: int = rng.randi_range(0, 140)
		var y0: int = rng.randi_range(0, 140)
		rx0[i] = x0
		ry0[i] = y0
		rx1[i] = x0 + w
		ry1[i] = y0 + h
	sx0 = rng.randi_range(0, 60)
	sy0 = rng.randi_range(0, 60)
	sx1 = sx0 + rng.randi_range(40, 120)
	sy1 = sy0 + rng.randi_range(40, 120)


func compute_e(px: int, py: int) -> void:
	exempt = false
	for i in range(n):
		if area(px - HW, py, px + HW, py + FH, i) > 0:
			in_e[i] = 1
			exempt = true
		else:
			in_e[i] = 0


func _init() -> void:
	rng.seed = 1507
	var trials: int = 300000
	var mism: int = 0
	var exempt_trials: int = 0
	var moving: int = 0
	for t in range(trials):
		gen()
		var px: int = rng.randi_range(8, 130)
		var py: int = rng.randi_range(0, 130)
		var sxp: int = rng.randi_range(-3, 3)
		var syp: int = rng.randi_range(-3, 3)
		compute_e(px, py)
		if exempt:
			exempt_trials += 1
		# oracle: x then y
		var ox: int = oracle_axis(px, py, sxp, 0)
		var oy: int = oracle_axis(px + ox, py, syp, 1)
		var ax: int = analytic_axis(px, py, sxp, 0)
		var ay: int = analytic_axis(px + ax, py, syp, 1)
		if ox != ax or oy != ay:
			mism += 1
			if mism <= 5:
				print("MISMATCH t=", t, " pos=", px, ",", py, " step=", sxp, ",", syp, " oracle=", ox, ",", oy, " analytic=", ax, ",", ay, " exempt=", exempt, " n=", n)
		if sxp != 0 or syp != 0:
			moving += 1
	print("trials=", trials, " exempt=", exempt_trials, " moving=", moving, " mismatches=", mism)

	# timing (indicative only: editor binary, --script)
	rng.seed = 99
	n = 16
	rx0.resize(n)
	ry0.resize(n)
	rx1.resize(n)
	ry1.resize(n)
	in_e.resize(n)
	for i in range(n):
		rx0[i] = 200 + i * 5
		ry0[i] = 0 + i * 3
		rx1[i] = rx0[i] + 24
		ry1[i] = ry0[i] + 24
		in_e[i] = 0
	exempt = false
	var reps: int = 100000
	var t0: int = Time.get_ticks_usec()
	var acc: int = 0
	for r in range(reps):
		acc += analytic_axis(100, 40, 3, 0)
		acc += analytic_axis(100, 40, -3, 1)
	var t1: int = Time.get_ticks_usec()
	for r in range(reps):
		acc += oracle_axis(100, 40, 3, 0)
		acc += oracle_axis(100, 40, -3, 1)
	var t2: int = Time.get_ticks_usec()
	print("analytic us per actor-tick (2 axes, K=16): ", float(t1 - t0) / float(reps), "  oracle: ", float(t2 - t1) / float(reps), " acc=", acc)

	# engine integer facts
	var a: int = -181
	var b: int = 256
	print("trunc -181/256=", a / b, " -362/256=", -362 / b, " -768/256=", -768 / b, " posmod(-1,48)=", posmod(-1, 48), " -7 % 3=", -7 % 3)
	var big: int = 1 << 24
	var f1: float = float(big)
	var f2: float = float(big + 1)
	print("float32 via Vector2: ", Vector2(float(big), 0.0).x, " ", Vector2(float(big + 1), 0.0).x, " ", Vector2(float((1 << 23) + 1), 0.0).x)
	var p: Node2D = Node2D.new()
	p.position = Vector2(float((1 << 23) + 1), float(-(1 << 23) - 1))
	print("Node2D.position round trip 2^23+1: ", int(p.position.x), " ", int(p.position.y))
	p.position = Vector2(float((1 << 24) + 1), 0.0)
	print("Node2D.position 2^24+1: ", int(p.position.x))
	p.free()
	var pi: PackedInt32Array = PackedInt32Array([1, 2, 3])
	var pj: PackedInt32Array = pi
	pj[0] = 9
	print("packed alias: pi[0]=", pi[0], " (value copy if 1)")
	quit()

